Then for k from 1 to 4*n:
   s := k % 2
   for i := A; i >= 0; i-- {
       for j := B; j >= 0; j-- {
           dp[i][j][k] = 0
           if s == 1 {
               for ii := i; ii <= A; ii++ {
                   f := lim - (ii-i)*50
                   if f >= 0 {
                       f = f/100
                       f += j
                       if f > B { f = B }
                       for jj := j; jj <= f; jj++ {
                           if i != ii || j != jj {
                               dp[i][j][k] = (dp[i][j][k] + dp[ii][jj][k-1]*c[ii][ii-i]*c[jj][jj-j]) % mod
                           }
                       }
                   }
               }
           } else {
               for ii := 0; ii <= i; ii++ {
                   f := lim - (i-ii)*50
                   if f >= 0 {
                       f = f/100
                       f = j - f
                       if f < 0 { f = 0 }
                       for jj := f; jj <= j; jj++ {
