      for j := B; j >= 0; j-- {
         s := k % 2
         dp[i][j][k] = 0
         if s == 1 {
            for ii := i; ii <= A; ii++ {
               f := lim - (ii - i)*50
               if f >= 0 {
                  f /= 100
                  f += j
                  if f > B { f = B }
                  for jj := j; jj <= f; jj++ {
                     if i != ii || j != jj {
                        dp[i][j][k] = (dp[i][j][k] + dp[ii][jj][k-1] * c[ii][ii-i] % mod * c[jj][jj-j] % mod) % mod
                     }
                  }
               }
